# ---------------------- Icon helpers --------------------------
def icon_data(name):
    raw = ICON_B64.get(name)
    return f"data:image/png;base64,{raw}" if raw else ""

def icon_img(name, width=38):
    src = icon_data(name)
    if src:
        st.markdown(
            f'<img src="{src}" width="{width}" style="vertical-align:middle;border-radius:10px;">',
            unsafe_allow_html=True,
        )


# -------------------- Authentication --------------------------
def db():
    conn = sqlite3.connect(DB_FILE)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            salt TEXT NOT NULL,
            role TEXT NOT NULL DEFAULT 'user',
            full_name TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        )
    """)
    conn.commit()
    return conn

def hash_password(password, salt=None):
    salt_bytes = os.urandom(16) if salt is None else bytes.fromhex(salt)
    digest = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt_bytes, 200_000
    )
    return digest.hex(), salt_bytes.hex()

def verify_password(password, password_hash, salt):
    digest, _ = hash_password(password, salt)
    return hmac.compare_digest(digest, password_hash)

def ensure_default_admin():
    conn = db()
    count = conn.execute("SELECT COUNT(*) FROM users").fetchone()[0]
    if count == 0:
        username = os.getenv("MAINT_ADMIN_USER", "admin")
        password = os.getenv("MAINT_ADMIN_PASSWORD", "Admin@123")
        ph, salt = hash_password(password)
        conn.execute(
            """INSERT INTO users(username,password_hash,salt,role,full_name,created_at)
               VALUES(?,?,?,?,?,?)""",
            (username, ph, salt, "admin", "Administrateur", datetime.now().isoformat()),
        )
        conn.commit()
    conn.close()

def authenticate(username, password):
    conn = db()
    row = conn.execute(
        """SELECT id,username,password_hash,salt,role,full_name,active
           FROM users WHERE username=?""", (username.strip(),)
    ).fetchone()
    conn.close()
    if not row or row[6] != 1:
        return None
    if verify_password(password, row[2], row[3]):
        return {
            "id": row[0], "username": row[1], "role": row[4],
            "full_name": row[5]
        }
    return None

def create_user(username, password, full_name, role="user"):
    username = username.strip()
    if not username or not password or not full_name.strip():
        return False, "Tous les champs sont obligatoires."
    if len(password) < 8:
        return False, "Le mot de passe doit contenir au moins 8 caractères."
    ph, salt = hash_password(password)
    conn = db()
    try:
        conn.execute(
            """INSERT INTO users(username,password_hash,salt,role,full_name,created_at)
               VALUES(?,?,?,?,?,?)""",
            (username, ph, salt, role, full_name.strip(), datetime.now().isoformat()),
        )
        conn.commit()
        return True, "Utilisateur créé avec succès."
    except sqlite3.IntegrityError:
        return False, "Ce nom d'utilisateur existe déjà."
    finally:
        conn.close()

def change_password(user_id, new_password):
    if len(new_password) < 8:
        return False, "Le mot de passe doit contenir au moins 8 caractères."
    ph, salt = hash_password(new_password)
    conn = db()
    conn.execute(
        "UPDATE users SET password_hash=?, salt=? WHERE id=?",
        (ph, salt, user_id),
    )
    conn.commit()
    conn.close()
    return True, "Mot de passe modifié."

def list_users():
    conn = db()
    data = pd.read_sql_query(
        "SELECT id, username, full_name, role, active, created_at FROM users ORDER BY id",
        conn
    )
    conn.close()
    return data

def toggle_user(user_id, active):
    conn = db()
    conn.execute("UPDATE users SET active=? WHERE id=?", (1 if active else 0, user_id))
    conn.commit()
    conn.close()


# ----------------------- Data layer ---------------------------
REQUIRED_COLUMNS = [
    "Date", "Machine", "Type_Maintenance", "Equipement",
    "Duree_Maintenance_h", "Cout_Maintenance_MAD",
    "Technicien", "Piece_Remplacee", "Statut"
]

def clean_data(raw):
    df = raw.copy()
    for c in ["Duree_Maintenance_h", "Cout_Maintenance_MAD"]:
        df[c] = pd.to_numeric(df[c], errors="coerce")
        df[c] = df[c].fillna(df[c].median() if not df[c].dropna().empty else 0)
        df[c] = df[c].clip(lower=0)

    for c in ["Machine", "Type_Maintenance", "Equipement", "Technicien", "Piece_Remplacee", "Statut"]:
        df[c] = df[c].fillna("Non renseigné").astype(str).str.strip()
        df.loc[df[c] == "", c] = "Non renseigné"

    df["Date"] = pd.to_datetime(df["Date"], errors="coerce")
    df["Date"] = df["Date"].fillna(pd.Timestamp.today().normalize())
    return df

@st.cache_data(show_spinner=False)
def load_data(file_path, modified_time):
    raw = pd.read_csv(file_path)
    missing_cols = [c for c in REQUIRED_COLUMNS if c not in raw.columns]
    if missing_cols:
        raise ValueError(f"Colonnes manquantes : {', '.join(missing_cols)}")
    return clean_data(raw)

def get_data():
    if not DATA_FILE.exists():
        pd.DataFrame(columns=REQUIRED_COLUMNS).to_csv(
            DATA_FILE, index=False, encoding="utf-8-sig"
        )
    return load_data(str(DATA_FILE), DATA_FILE.stat().st_mtime)

def append_intervention(values):
    # Verrou logique simple pour une application locale mono-instance.
    # Pandas concat + to_csv conserve l'historique et rend la nouvelle ligne
    # immédiatement disponible au prochain rerun Streamlit.
    raw = pd.read_csv(DATA_FILE)
    new_row = pd.DataFrame([values])
    raw = pd.concat([raw, new_row], ignore_index=True)
    raw.to_csv(DATA_FILE, index=False, encoding="utf-8-sig")
    load_data.clear()

def format_mad(x):
    return f"{x:,.0f} MAD".replace(",", " ")

def safe_options(series):
    return sorted([str(x) for x in series.dropna().unique()])

