# ----------------------- Dashboard ----------------------------
def dashboard_page():
    df = get_data()
    st.markdown(
        '<div class="hero"><h1>Tableau de bord maintenance</h1>'
        '<p>Vue opérationnelle des interventions, coûts, durées et équipements.</p></div>',
        unsafe_allow_html=True
    )

    # Filtres
    with st.container():
        st.markdown('<div class="section">', unsafe_allow_html=True)
        st.markdown("#### 🔎 Filtres interactifs")
        c1, c2, c3, c4 = st.columns(4)

        min_date = df["Date"].min().date() if not df.empty else date.today()
        max_date = df["Date"].max().date() if not df.empty else date.today()
        with c1:
            dates = st.date_input(
                "Période", value=(min_date, max_date),
                min_value=min_date, max_value=max_date
            )
        with c2:
            machines = st.multiselect("Machine", safe_options(df["Machine"]), default=[])
        with c3:
            types = st.multiselect("Type de maintenance", safe_options(df["Type_Maintenance"]), default=[])
        with c4:
            statuses = st.multiselect("Statut", safe_options(df["Statut"]), default=[])

        f = df.copy()
        if isinstance(dates, tuple) and len(dates) == 2:
            f = f[(f["Date"].dt.date >= dates[0]) & (f["Date"].dt.date <= dates[1])]
        if machines:
            f = f[f["Machine"].isin(machines)]
        if types:
            f = f[f["Type_Maintenance"].isin(types)]
        if statuses:
            f = f[f["Statut"].isin(statuses)]

        st.markdown(
            f'<div class="small-muted">Données nettoyées : <b>{len(f):,}</b> '
            f'interventions affichées sur <b>{len(df):,}</b> au total.</div>',
            unsafe_allow_html=True
        )
        st.markdown("</div>", unsafe_allow_html=True)

    # KPI
    n = len(f)
    total_cost = f["Cout_Maintenance_MAD"].sum() if n else 0
    total_hours = f["Duree_Maintenance_h"].sum() if n else 0
    avg_cost = f["Cout_Maintenance_MAD"].mean() if n else 0
    corrective = (f["Type_Maintenance"].eq("Corrective").mean() * 100) if n else 0
    completed = (f["Statut"].eq("Terminée").mean() * 100) if n else 0

    cols = st.columns(6)
    kpis = [
        ("Interventions", f"{n:,}", "Volume filtré", "controle.png"),
        ("Coût total", format_mad(total_cost), "Dépenses maintenance", "paquet.png"),
        ("Temps total", f"{total_hours:,.1f} h", "Temps d'intervention", "efficacite.png"),
        ("Coût moyen", format_mad(avg_cost), "Par intervention", "performance.png"),
        ("Corrective", f"{corrective:.1f} %", "Part du correctif", "surveiller.png"),
        ("Terminée", f"{completed:.1f} %", "Taux de clôture", "gestion-de-projet.png"),
    ]
    for col, (label, value, note, icon) in zip(cols, kpis):
        with col:
            st.markdown(
                f'<div class="kpi"><img src="{icon_data(icon)}" width="35" '
                f'style="border-radius:9px;"><div class="kpi-label">{label}</div>'
                f'<div class="kpi-value">{value}</div><div class="kpi-note">{note}</div></div>',
                unsafe_allow_html=True
            )

    if f.empty:
        st.info("Aucune donnée ne correspond aux filtres sélectionnés.")
        return

    # Graphiques
    st.markdown("### 📊 Analyses")
    g1, g2 = st.columns(2)

    with g1:
        st.markdown("**Évolution mensuelle du coût de maintenance**")
        monthly = f.set_index("Date").resample("MS")["Cout_Maintenance_MAD"].sum()
        fig, ax = plt.subplots(figsize=(7.2, 3.6))
        ax.plot(monthly.index, monthly.values, marker="o", linewidth=2.4)
        ax.set_ylabel("MAD")
        ax.grid(alpha=.22)
        fig.autofmt_xdate()
        fig.tight_layout()
        st.pyplot(fig, use_container_width=True)
        plt.close(fig)

    with g2:
        st.markdown("**Répartition par type de maintenance**")
        typ = f["Type_Maintenance"].value_counts()
        fig, ax = plt.subplots(figsize=(7.2, 3.6))
        ax.barh(typ.index, typ.values)
        ax.set_xlabel("Interventions")
        ax.invert_yaxis()
        ax.grid(axis="x", alpha=.22)
        fig.tight_layout()
        st.pyplot(fig, use_container_width=True)
        plt.close(fig)

    g3, g4 = st.columns(2)
    with g3:
        st.markdown("**Machines avec le plus d'interventions**")
        machine = f["Machine"].value_counts().head(10).sort_values()
        fig, ax = plt.subplots(figsize=(7.2, 3.8))
        ax.barh(machine.index, machine.values)
        ax.set_xlabel("Interventions")
        ax.grid(axis="x", alpha=.22)
        fig.tight_layout()
        st.pyplot(fig, use_container_width=True)
        plt.close(fig)

    with g4:
        st.markdown("**Coût par équipement**")
        equip = f.groupby("Equipement")["Cout_Maintenance_MAD"].sum().sort_values()
        fig, ax = plt.subplots(figsize=(7.2, 3.8))
        ax.barh(equip.index, equip.values)
        ax.set_xlabel("MAD")
        ax.grid(axis="x", alpha=.22)
        fig.tight_layout()
        st.pyplot(fig, use_container_width=True)
        plt.close(fig)

    st.markdown("### 🧾 Données filtrées")
    display_df = f.copy()
    display_df["Date"] = display_df["Date"].dt.strftime("%Y-%m-%d")
    display_df["Cout_Maintenance_MAD"] = display_df["Cout_Maintenance_MAD"].round(2)
    display_df["Duree_Maintenance_h"] = display_df["Duree_Maintenance_h"].round(1)
    st.dataframe(display_df, use_container_width=True, hide_index=True)


# --------------------- Add intervention -----------------------
def add_page():
    st.markdown(
        '<div class="hero"><h1>Nouvelle intervention</h1>'
        '<p>Ajoutez une intervention : elle sera enregistrée dans le CSV central '
        'et les KPI seront recalculés automatiquement.</p></div>',
        unsafe_allow_html=True
    )

    df = get_data()
    st.markdown("#### 📝 Informations à saisir")
    st.caption("Remplissez les champs ci-dessous. * = champ obligatoire.")
    with st.form("new_intervention", clear_on_submit=True):
        c1, c2, c3 = st.columns(3)
        with c1:
            d = st.date_input("Date de l'intervention *", value=date.today(), help="Date à laquelle l'intervention a eu lieu ou est planifiée.")
            machine = st.text_input("Identifiant / nom de la machine *", placeholder="Ex. M-21", help="Code unique ou nom de la machine concernée.")
            equipment = st.selectbox("Équipement / famille de machine *", safe_options(df["Equipement"]) or ["Presse", "Pompe", "Robot", "Compresseur"])
        with c2:
            maintenance_type = st.selectbox(
                "Type de maintenance *",
                ["Préventive", "Corrective", "Prédictive", "Améliorative"]
            )
            duration = st.number_input("Durée de l'intervention (heures) *", min_value=0.0, step=0.1, help="Temps consacré à l'intervention.")
            cost = st.number_input("Coût de maintenance (MAD) *", min_value=0.0, step=100.0, help="Coût total estimé ou réel de l'intervention.")
        with c3:
            technician = st.text_input("Technicien responsable *", placeholder="Ex. TECH-14")
            pieces = st.text_input("Pièce remplacée", placeholder="Ex. Capteur de température", help="Laissez vide si aucune pièce n'a été remplacée.")
            status = st.selectbox("Statut de l'intervention *", ["Terminée", "En cours", "Planifiée", "Annulée"])

        submitted = st.form_submit_button("💾 Enregistrer l'intervention", use_container_width=True)

    if submitted:
        if not machine.strip() or not technician.strip():
            st.error("Les champs obligatoires sont : Machine et Technicien responsable.")
            return
        row = {
            "Date": d.isoformat(),
            "Machine": machine.strip(),
            "Type_Maintenance": maintenance_type,
            "Equipement": equipment,
            "Duree_Maintenance_h": duration,
            "Cout_Maintenance_MAD": cost,
            "Technicien": technician.strip(),
            "Piece_Remplacee": pieces.strip() or "Non renseigné",
            "Statut": status,
        }
        append_intervention(row)
        st.success("Intervention enregistrée. Les données, KPI et graphiques sont maintenant à jour.")
        st.rerun()


# ----------------------- Admin page ----------------------------
def admin_page():
    if st.session_state.user["role"] != "admin":
        st.error("Accès réservé à l'administrateur.")
        return

    st.markdown(
        '<div class="hero"><h1>Administration</h1>'
        '<p>Gestion des comptes utilisateurs et contrôle des accès.</p></div>',
        unsafe_allow_html=True
    )

    a, b = st.columns(2)
    with a:
        st.markdown("#### 👤 Créer un utilisateur")
        st.caption("Tous les champs marqués * sont obligatoires. Le nom d'utilisateur doit être unique.")
        with st.form("create_user"):
            username = st.text_input("Nom d'utilisateur *", placeholder="Ex. yassine.maintenance")
            fullname = st.text_input("Nom complet de l'utilisateur *", placeholder="Ex. Yassine El Amrani")
            password = st.text_input("Mot de passe *", type="password", placeholder="Minimum 8 caractères")
            role = st.selectbox("Rôle du compte *", ["user", "admin"])
            ok = st.form_submit_button("Créer le compte", use_container_width=True)
        if ok:
            success, msg = create_user(username, password, fullname, role)
            (st.success if success else st.error)(msg)

    with b:
        st.markdown("#### Modifier mon mot de passe")
        with st.form("change_pwd"):
            p1 = st.text_input("Nouveau mot de passe", type="password")
            p2 = st.text_input("Confirmer", type="password")
            change = st.form_submit_button("Modifier", use_container_width=True)
        if change:
            if p1 != p2:
                st.error("Les deux mots de passe sont différents.")
            else:
                success, msg = change_password(st.session_state.user["id"], p1)
                (st.success if success else st.error)(msg)

    st.markdown("#### 📋 Comptes enregistrés")
    st.caption("Pour des raisons de sécurité, les mots de passe ne sont jamais affichés ici : seuls leurs empreintes cryptographiques sont conservées dans la base.")
    users = list_users()
    st.dataframe(users, use_container_width=True, hide_index=True)

    st.markdown("#### 🗄️ Où sont stockés les utilisateurs ?")
    st.info(
        f"La base SQLite est créée automatiquement dans le même dossier que l'application : "
        f"`{DB_FILE.name}`. Elle contient les comptes, rôles, dates de création et empreintes des mots de passe. "
        "Vous pouvez voir les comptes ci-dessus depuis l'application. Le mot de passe original n'est volontairement pas récupérable."
    )
    st.caption("Pour ouvrir cette base comme administrateur technique, vous pouvez utiliser un logiciel SQLite tel que DB Browser for SQLite, en ouvrant le fichier `maintenance_users.db`.")

    for _, row in users.iterrows():
        if row["id"] == st.session_state.user["id"]:
            continue
        label = "Désactiver" if row["active"] else "Réactiver"
        if st.button(f"{label} : {row['username']}", key=f"user_{row['id']}"):
            toggle_user(row["id"], not bool(row["active"]))
            st.rerun()


# ------------------------- App shell ---------------------------
def main():
    ensure_default_admin()

    if "user" not in st.session_state:
        login_page()
        return

    # Rafraîchissement automatique pour faire apparaître les nouvelles données
    # enregistrées par un autre utilisateur sur la même application locale.
    if st_autorefresh is not None:
        st_autorefresh(interval=15000, key="maintenance_auto_refresh")

    user = st.session_state.user

    with st.sidebar:
        icon_img("gestion-de-projet.png", 54)
        st.markdown(f"## {APP_NAME}")
        st.caption("Gestion de maintenance industrielle")
        st.markdown(f"**{user['full_name']}**")
        st.markdown(f'<span class="badge">{user["role"].upper()}</span>', unsafe_allow_html=True)
        st.divider()

        pages = ["📊 Dashboard", "➕ Nouvelle intervention"]
        if user["role"] == "admin":
            pages.append("⚙️ Administration")
        pages.append("ℹ️ À propos")

        page = st.radio("Navigation", pages)

        st.divider()
        if st.button("🚪 Déconnexion", use_container_width=True):
            st.session_state.pop("user", None)
            st.rerun()

        st.caption("Actualisation automatique : 15 s")

    if page == "📊 Dashboard":
        dashboard_page()
    elif page == "➕ Nouvelle intervention":
        add_page()
    elif page == "⚙️ Administration":
        admin_page()
    else:
        st.markdown(
            '<div class="hero"><h1>MAINTENANCE PRO</h1>'
            '<p>Application Streamlit locale pour le pilotage des opérations de maintenance.</p></div>',
            unsafe_allow_html=True
        )
        st.markdown("""
        ### Architecture des données
        - **dataset_maintenance.csv** : historique des interventions, partagé par l'application.
        - **maintenance_users.db** : fichier SQLite créé automatiquement au premier lancement pour les comptes,
          rôles et mots de passe hachés. Il apparaît automatiquement à côté de `app.py`.
        - **app.py** : interface, nettoyage, calcul des KPI, graphiques et écriture des nouvelles interventions.

        ### Mise à jour automatique
        Lorsqu'un utilisateur enregistre une intervention, `app.py` ajoute une ligne au CSV,
        vide le cache Pandas et relance l'interface. Le tableau de bord recalcule alors les KPI
        et les graphiques à partir du fichier actualisé.

        L'application vérifie aussi la date de modification du CSV. En complément, le tableau
        de bord se rafraîchit toutes les 15 secondes : une saisie faite par un autre utilisateur
        sur la même instance devient donc visible sans recopier manuellement les données.

        ### Pour un vrai déploiement multi-postes
        Le CSV est excellent pour un prototype/local, mais pour plusieurs postes simultanés,
        il est recommandé de remplacer la couche CSV par PostgreSQL/MySQL. La même interface
        Streamlit peut alors interroger une base centrale avec transactions et contrôle de concurrence.
        """)

if __name__ == "__main__":
    main()
